mapper.update:
UPDATE sys_user
SET last_login_time = #{lastLoginTime}, update_time = NOW()
WHERE id = #{userId}

mapper.select:
SELECT u.id, u.username, u.password, u.real_name, u.phone, u.email, u.department, u.dept_id, u.position, u.role, u.status, u.last_login_time, u.create_time, u.update_time, u.deleted, u.weekly_permission, u.monthly_permission, u.is_admin, d.dept_name FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id WHERE u.deleted = 0
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND u.department = #{department}
AND u.dept_id = #{deptId}
AND u.role = #{role}
AND u.status = #{status}
ORDER BY u.create_time DESC
